#include <cstddef>
#include <iostream>
#include <memory>

class Pool
{
public:
    Pool(std::size_t blockSize, std::size_t count) {}
    void* allocate() { return nullptr; }
    void deallocate(void* p) {}

private:
    struct FreeBlock
    {
        FreeBlock* next;
    };
    FreeBlock* m_free{};
};

int main()
{
    Pool pool{32, 4};
    std::cout << pool.allocate() << '\n';
}
